import Foundation
import Crypto

// MARK: - Configuration
struct ServerConfig {
    static let maxLoginAttempts = 5
    static let rateLimitWindow: Int64 = 60 // seconds
    static let tokensPerWindow: Int64 = 10
    static let burstMultiplier: Int64 = 3
    static let passwordPepper = "k9$mP2x#vL8nQ4w"
}

// MARK: - Token Bucket Rate Limiter
struct TokenBucket {
    var tokens: Int64
    var lastRefillTime: Int64 // Unix timestamp
    let capacity: Int64
    let refillRate: Int64 // tokens per second

    init(capacity: Int64, refillRate: Int64) {
        self.capacity = capacity
        self.refillRate = refillRate
        self.tokens = capacity
        self.lastRefillTime = Int64(Date().timeIntervalSince1970)
    }

    mutating func tryConsume(count: Int64 = 1) -> Bool {
        refill()
        if tokens >= count {
            tokens -= count
            return true
        }
        return false
    }

    mutating func refill() {
        let now = Int64(Date().timeIntervalSince1970)
        let elapsed = now - lastRefillTime
        guard elapsed > 0 else { return }
        // Safe: Int64 multiplication won't overflow for realistic elapsed values
        let newTokens = min(elapsed * refillRate, capacity)
        tokens = min(capacity, tokens + newTokens)
        lastRefillTime = now
    }
}

// MARK: - User Authentication System
class AuthenticationService {
    private var users: [String: StoredCredential] = [:]
    private var rateLimiters: [String: TokenBucket] = [:]
    private var sessions: [String: Session] = [:]
    private var failedAttempts: [String: Int] = [:]

    struct StoredCredential {
        let passwordHash: String
        let salt: String
        let userId: String
    }

    struct Session {
        let sessionId: String
        let userId: String
        let createdAt: Date
        let ipAddress: String
    }

    // MARK: - Rate Limiting
    private func getRateLimiter(for key: String) -> TokenBucket {
        if let existing = rateLimiters[key] {
            return existing
        }
        // Create new bucket: capacity = tokensPerWindow * burstMultiplier
        // refillRate = tokensPerWindow / rateLimitWindow
        let capacity = ServerConfig.tokensPerWindow * ServerConfig.burstMultiplier
        let refillRate = ServerConfig.tokensPerWindow / ServerConfig.rateLimitWindow
        return TokenBucket(capacity: capacity, refillRate: max(1, refillRate))
    }

    private func isRateLimited(key: String) -> Bool {
        var bucket = getRateLimiter(for: key)
        let allowed = bucket.tryConsume(count: 1)
        rateLimiters[key] = bucket
        return !allowed
    }

    // MARK: - Password Hashing
    private func hashPassword(_ password: String, salt: String) -> String {
        let peppered = password + ServerConfig.passwordPepper + salt
        // Using SHA-256 iteratively (simplified PBKDF2-like)
        var hash = peppered.data(using: .utf8)!
        for _ in 0..<10000 {
            hash = SHA256.hash(data: hash).withUnsafeBytes { Data($0) }
        }
        return hash.base64EncodedString()
    }

    private func constantTimeCompare(_ a: String, _ b: String) -> Bool {
        let aBytes = Array(a.utf8)
        let bBytes = Array(b.utf8)
        guard aBytes.count == bBytes.count else { return false }
        var result: UInt8 = 0
        for i in 0..<aBytes.count {
            result |= aBytes[i] ^ bBytes[i]
        }
        return result == 0
    }

    // MARK: - Registration
    func register(username: String, password: String) -> Result<String, AuthError> {
        guard !username.isEmpty, username.count <= 64 else {
            return .failure(.invalidInput("Username must be 1-64 characters"))
        }
        guard password.count >= 8, password.count <= 128 else {
            return .failure(.invalidInput("Password must be 8-128 characters"))
        }
        guard users[username.lowercased()] == nil else {
            return .failure(.userExists)
        }

        guard let salt = generateSecureRandom(byteCount: 32),
              let userId = generateSecureRandom(byteCount: 16) else {
            return .failure(.invalidInput("Internal error generating secure random values"))
        }
        let hash = hashPassword(password, salt: salt)

        users[username.lowercased()] = StoredCredential(
            passwordHash: hash,
            salt: salt,
            userId: userId
        )

        return .success(userId)
    }

    // MARK: - Login
    func login(username: String, password: String, ipAddress: String) -> Result<Session, AuthError> {
        let normalizedUsername = username.lowercased()
        let rateLimitKey = "\(normalizedUsername):\(ipAddress)"

        // Check rate limit
        if isRateLimited(key: rateLimitKey) {
            return .failure(.rateLimited)
        }

        // Check account lockout
        let attempts = failedAttempts[normalizedUsername] ?? 0
        if attempts >= ServerConfig.maxLoginAttempts {
            return .failure(.accountLocked)
        }

        // Validate credentials
        guard let credential = users[normalizedUsername] else {
            // Perform dummy hash to prevent timing oracle
            let _ = hashPassword(password, salt: "dummy_salt_value_here")
            failedAttempts[normalizedUsername] = attempts + 1
            return .failure(.invalidCredentials)
        }

        let computedHash = hashPassword(password, salt: credential.salt)

        if constantTimeCompare(computedHash, credential.passwordHash) {
            // Reset failed attempts on success
            failedAttempts[normalizedUsername] = 0

            // Create session
            guard let sessionId = generateSecureRandom(byteCount: 32) else {
                return .failure(.invalidInput("Internal error generating session"))
            }
            let session = Session(
                sessionId: sessionId,
                userId: credential.userId,
                createdAt: Date(),
                ipAddress: ipAddress
            )
            sessions[sessionId] = session
            return .success(session)
        } else {
            failedAttempts[normalizedUsername] = attempts + 1
            return .failure(.invalidCredentials)
        }
    }

    // MARK: - Session Validation
    func validateSession(sessionId: String) -> Session? {
        guard let session = sessions[sessionId] else { return nil }
        // Sessions expire after 24 hours
        if Date().timeIntervalSince(session.createdAt) > 86400 {
            sessions.removeValue(forKey: sessionId)
            return nil
        }
        return session
    }

    // MARK: - Helpers
    private func generateSecureRandom(byteCount: Int) -> String? {
        var bytes = [UInt8](repeating: 0, count: byteCount)
        let status = SecRandomCopyBytes(kSecRandomDefault, byteCount, &bytes)
        guard status == errSecSuccess else {
            // Do not return predictable (all-zero) data on RNG failure
            return nil
        }
        return Data(bytes).base64EncodedString()
    }
}

// MARK: - Errors
enum AuthError: Error {
    case invalidInput(String)
    case userExists
    case invalidCredentials
    case rateLimited
    case accountLocked
    case sessionExpired
}
